import random
import time
import sys

def init_prng(seed):
    random._inst = random.Random(seed)
    random.seed = random._inst.seed
    random.randint = random._inst.randint

def get_draw():
    draw = set()
    while len(draw) != 6:
        draw.add(random.randint(1, 70))
    return sorted(list(draw))

def simulate_draws(seed, count=1000):
    draws = []
    init_prng(seed)
    for _ in range(count):
        draws.append(get_draw())
    return draws

def verify_draw(real_draw, predicted_draw):
    real_set = set(real_draw)
    pred_set = set(predicted_draw)
    return len(real_set.intersection(pred_set)) >= 4

def extract_draw_nums(line):
    try:
        start = line.index('{') + 1
        end = line.index('}')
        nums_str = line[start:end]
        return set(int(x.strip()) for x in nums_str.split(','))
    except:
        return None

def extract_profit(line):
    try:
        return int(line.split('$')[1])
    except:
        return None

def connect_and_play(seed, verbose=False):
    init_prng(seed)
    draws = []
    for _ in range(40):
        draws.append(get_draw())

    try:
        r = remote('crypto.chal.csaw.io', 5000, level='error')
        r.recvuntil(b"buy?")
        r.sendline(b"40")

        # Submit our predicted tickets
        for i in range(40):
            nums = draws[i]
            r.recvuntil(f"ticket {i+1}".encode())
            for num in nums:
                r.sendline(str(num).encode())

        # Monitor the output
        while True:
            try:
                line = r.recvline().decode().strip()
                if verbose:
                    print(line)

                if "csawctf{" in line:
                    print("\nFOUND FLAG:", line)
                    r.close()
                    return True, line

                if "Draw" in line:
                    draw_nums = extract_draw_nums(line)
                    if draw_nums:
                        found_match = False
                        for pred in draws:
                            if len(draw_nums.intersection(set(pred))) >= 4:
                                found_match = True
                                break
                        if not found_match:
                            r.close()
                            return False, None

                if "loss" in line:
                    r.close()
                    return False, None

            except EOFError:
                r.close()
                return False, None

    except Exception as e:
        print("Error:", str(e))
        return False, None

def main():
    base_time = int(time.time())
    print(f"Current timestamp: {base_time}")

    # Try various seed offsets
    for offset in range(-100000, 100000):
        seed = base_time + offset
        if offset % 100 == 0:
            print(f"Trying seed: {seed} (offset {offset})")

        success, flag = connect_and_play(seed)
        if success:
            print(f"\nSuccess with seed {seed}!")
            print(f"Flag: {flag}")
            break

