import time

def test_seed(seed, first_draw):
    random.seed(seed)
    test_draw = set([])
    while len(test_draw) != 6:
        test_draw.add(random.randint(1,70))
    return test_draw == first_draw

def find_seed(target_draw):
    current_time = int(time.time())
    # Test seeds around current time
    for test_seed in range(current_time - 100, current_time + 100):
        if test_seed(test_seed, target_draw):
            return test_seed
    return None

def generate_draws(seed, num_draws=1000000):
    random.seed(seed)
    draws = []
    for _ in range(num_draws):
        draw = set([])
        while len(draw) != 6:
            draw.add(random.randint(1,70))
        draws.append(draw)
    return draws

def submit_tickets(r, tickets):
    r.sendline(b"40")  # Submit 40 tickets
    for ticket in tickets:
        for num in sorted(ticket):
            r.sendline(str(num).encode())
    return True

def main():
    for attempt in range(100):
        try:
            # Connect to server
            conn = remote('crypto.chal.csaw.io', 5000)

            # Get first draw
            conn.recvuntil(b"consecutive rounds of the lottery!")
            first_line = conn.recvline().decode()
            if not "Draw" in first_line:
                conn.close()
                continue

            # Parse first draw
            draw_str = first_line.split("{")[1].split("}")[0]
            first_draw = set(int(x.strip()) for x in draw_str.split(","))

            # Find the seed
            seed = find_seed(first_draw)
            if not seed:
                conn.close()
                continue

            # Generate all future draws
            draws = generate_draws(seed)

            # Create optimal tickets based on first 40 draws
            tickets = []
            for draw in draws[:40]:
                tickets.append(draw)

            # Submit tickets
            conn = remote('crypto.chal.csaw.io', 5000)
            conn.recvuntil(b"buy?")
            if not submit_tickets(conn, tickets):
                conn.close()
                continue

            # Monitor output
            while True:
                try:
                    line = conn.recvline().decode()
                    print(line)
                    if "csawctf{" in line:
                        print(f"Found flag in attempt {attempt + 1}!")
                        conn.close()
                        return
                except:
                    break

            conn.close()

        except:
            continue

if __name__ == "__main__":
    main()

